// Judgment-call cadence, not brief-specified (see the trigger node's own notes): 3/14/45/90 days
// between touches, then every 90 days (quarterly) after wave 4 - a reasonable escalating-then-
// steady nurture rhythm, not a decided number from the source docs.
const INTERVALS_DAYS = [3, 14, 45, 90];
const QUARTERLY_DAYS = 90;
const MS_PER_DAY = 86400000;

function asArray(item) {
  const json = item.json;
  if (Array.isArray(json)) return json;
  if (json && json.data && Array.isArray(json.data.opportunities)) return json.data.opportunities;
  if (json && Array.isArray(json.opportunities)) return json.opportunities;
  return [];
}

const now = new Date();
const due = [];

for (const opp of $input.all().flatMap(asArray)) {
  const wave = opp.nurtureWave || 0;
  if (!opp.lastNurtureTouchAt) {
    due.push({ ...opp, nextWave: 1 });
    continue;
  }
  const intervalDays = wave < INTERVALS_DAYS.length ? INTERVALS_DAYS[wave] : QUARTERLY_DAYS;
  const daysSince = (now - new Date(opp.lastNurtureTouchAt)) / MS_PER_DAY;
  if (daysSince >= intervalDays) {
    due.push({ ...opp, nextWave: wave + 1 });
  }
}

return due.map((opp) => ({ json: opp }));

const body = $input.first().json;
const textBlock = (body.content || []).find((b) => b.type === 'text');
if (!textBlock) throw new Error('Claude response had no text content block.');
return [{ json: { draftText: textBlock.text } }];
